        fc::ConverterEditOptions poseEdit;poseEdit.bones={{32,{8,0,0},0,1,0}};fc::ConverterWallRunSequence corrected;expect(fc::applyConverterWallRunEdits(document,poseEdit,document.cuts,corrected,failure),"Whole local correction applies: "+failure);for(unsigned stage=0;stage<3;++stage)expect(fc::angleBetween(corrected.stages[stage].animation.clip.frames.front()[32].q,document.stages[stage].animation.clip.frames.front()[32].q)>.1f,"Whole local correction reaches every stage");
