    for(std::size_t frame=0;frame<raw.frames.size();++frame)raw.frames[frame][32].q=(raw.frames[frame][32].q*fc::Quat::axis({1,0,0},.1f*std::sin(float(frame)*.07f))).unit();
    const auto input=folder/"complete-source.hkx";std::vector<std::string> warnings;write(input,fc::writeConverterHkx(raw,source.base,warnings));const auto savedInput=read(input);source=fc::loadConverterEditor(input,base/"pack.json","runUp","runUp");
    fc::ConverterEditOptions edits;edits.autoCalibration=false;edits.rootOffset={2,0,0};edits.contacts={{0,.1f,.9f,.1f,.8f}};edits.bones={{32,{5,0,0},.1f,.9f,.1f}};
    fc::ConverterWallRunSequence sequence;expect(fc::authorWallRunSequence(source,edits,"runRight",{.8f,3.2f},sequence,failure),"Author complete source: "+failure);expect(sequence.stages.size()==3&&sequence.primary=="runRight","Complete source emits one direction's three timing roles");
    const auto whole=fc::applyConverterEdits(source,edits);const auto frameInterval=whole.clip.duration/float(whole.clip.frames.size()-1);std::vector<fc::ConverterTimelinePart> parts;
    for(const auto& stage:sequence.stages){expect(stage.document.direction=="runRight"&&stage.animation.config.at("version")==2,"Each timing role has the selected direction and source playback");parts.push_back({stage.document.slot,stage.animation.clip});const auto again=fc::applyConverterEdits(stage.document,stage.options);expect(again.clip.frames.size()==stage.animation.clip.frames.size(),"Returning to a generated role retains frames");for(std::size_t frame=0;frame<again.clip.frames.size();++frame)pose(again.clip.frames[frame],stage.animation.clip.frames[frame],"Returning to generated role preserves edits");expect(again.config.at("contacts")==stage.animation.config.at("contacts"),"Returning to generated role preserves source Contacts");}
